INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.108.0',
  '2026-10-01',
  'Игры: лабиринт',
  E'Четвёртая игра — лабиринт. Перед стартом выбирается размер: обычный помещается в экран целиком, большой вдвое больше, а гигантский — в десять раз по каждой стороне, и поле едет за точкой по мере движения. Рекорд у каждого размера свой: минута в маленьком лабиринте и минута в гигантском — разные достижения.\n\nТочка идёт туда, куда вы зажали палец или курсор. Если прямо там стена, она сама свернёт в сторону вашего пальца по открытому коридору — вести её можно одним пальцем, не целясь в повороты. На компьютере работают стрелки. Пройденный путь подкрашивается, чтобы не ходить по кругу.\n\nСверху три кнопки: шестерёнка открывает настройки игры (картинки для фона), «скорость» меняет, насколько быстро бежит точка, «масштаб» — крупность лабиринта. Стиль стенок — кирпич, камень, дерево, неон, живая изгородь или лёд — выбирается случайно при каждом запуске; позже набор можно будет пополнять картинками из админки.\n\nЛабиринты строятся на сервере по запросу, каждый раз новые.',
  E'Генератор — internal/games/maze.go, «раскопка» (recursive backtracker, итеративно): лабиринт идеальный, между любыми клетками ровно один путь. Отдаётся GET /games/maze?cols=&rows=&seed= строкой на строку, по hex-символу на клетку (биты открытых сторон): сорок тысяч клеток — 40 КБ текста вместо мегабайта JSON-массивов. Тот же seed даёт тот же лабиринт (пригодится для «наперегонки» с другом). Потолок 120 000 клеток, сторона 5…400, 200×300 генерируется за 16 мс. Тесты: связность обходом в ширину, согласованность проходов с обеих сторон, повторяемость по seed, зажим размеров.\n\nРекорды по размерам раздельные: код игры несёт вариант через двоеточие (maze:huge), splitGame проверяет базу по gameRules и вариант регуляркой; наборы картинок остались общими для игры. На клиенте bestScore выбирает лучший из вариантов для плитки, а экран выбора размера показывает рекорд каждого.\n\nПоле — canvas: стенки рисуются сплошной сеткой полос, залитой паттерном, после чего проходы прорезаются clearRect. Холст прозрачный, поэтому в проходах виден фон игры, а прорезать дешевле, чем рисовать каждую стенку отдельно; рисуется только видимый прямоугольник клеток, так что гигантский лабиринт не тормозит. Шесть стилей стенок (apps/games/maze/walls.ts) — плитка 24×24, нарисованная кодом, размножается createPattern.\n\nУправление «как в Пакмане»: направление выбирается у центра клетки по вектору от точки к пальцу — сначала главная ось, при стене вторая. Первая версия шла строго по главной оси и вставала намертво, стоило коридору уйти в сторону, — поймано на проверке. dt в цикле ограничен 50 мс, иначе после возврата во вкладку точка телепортируется сквозь стены.\n\nПроверено в браузере: три размера, движение и повороты по пальцу, подкраска пройденного, камера за точкой на «большом», кнопки скорости и масштаба с сохранением в localStorage, шестерёнка в настройки игры, картинка фона в проходах. Запись рекордов вариантов проверена curl-ом (maze:normal и maze:huge раздельно, кривой вариант — 400).'
);
-- +goose StatementEnd

